<?php
declare(strict_types=1);
require_once __DIR__.'/../ledger/database.php';
if(PHP_SAPI!=='cli'||!in_array(count($argv),[3,4],true)){fwrite(STDERR,"Usage: php verify-mariadb-restore.php DATABASE --save EXPECTED_JSON | RESTORED_DB EXPECTED_JSON\n");exit(2);}
function snapshotMaria(PDO $pdo):array{$tables=['agencies','users','accounts','entries','audit_log','login_limits','chat_presence','chat_messages','chat_threads'];$counts=[];foreach($tables as $t)$counts[$t]=(int)$pdo->query('SELECT COUNT(*) FROM `'.$t.'`')->fetchColumn();$balances=$pdo->query('SELECT a.id,a.opening,COALESCE(SUM(CASE WHEN e.deleted=0 THEN e.debit ELSE 0 END),0) debit,COALESCE(SUM(CASE WHEN e.deleted=0 THEN e.credit ELSE 0 END),0) credit FROM accounts a LEFT JOIN entries e ON e.account_id=a.id AND e.agency_id=a.agency_id GROUP BY a.id,a.opening ORDER BY a.id')->fetchAll(PDO::FETCH_ASSOC);return [$counts,$balances];}
putenv('LEDGER_DB_NAME='.$argv[1]);$a=connectLedgerDatabase();$x=snapshotMaria($a);if($argv[2]==='--save'){if(count($argv)!==4){fwrite(STDERR,"Missing expected snapshot path\n");exit(2);}file_put_contents($argv[3],json_encode($x,JSON_THROW_ON_ERROR));echo "Saved pre-backup MariaDB snapshot\n";exit(0);}if(count($argv)!==3){fwrite(STDERR,"Unexpected snapshot arguments\n");exit(2);}$expected=json_decode((string)file_get_contents($argv[2]),true,512,JSON_THROW_ON_ERROR);if($x!==$expected){fwrite(STDERR,"FAIL MariaDB backup restore counts/balances differ\n".var_export(['expected'=>$expected,'restored'=>$x],true)."\n");exit(1);}echo "PASS MariaDB backup restore counts and per-account opening/debit/credit totals match\n";
